-- 20261107_historico_temporadas.sql — APLICADO EM PROD via MCP (s22, 07/11/2026)
-- Histórico 2008/09–2025/26: season_team_history (V-E-D por time/temporada) e season_champions.
-- Fontes: planilha "Histórico da Liga Bola Presa" (08/09–18/19) e jogos do banco (19/20–25/26).
-- Mapa de times: Interlagos→Pinheiros; Almada/Rio de Janeiro/New World Vultures→RJ Drugdealers;
-- Alphaville Yellow Caps→Campinas Color Blinds; Calangos→Carcarás; HorizonHorse→Old Devils; Lighthalzen=Light City.
-- Times extintos novos: San Diego Spikes, São Bernardo Furnitures, Natal Suncity, Vila Real Junkheads,
-- Bauru Whitout Tomato is Mixed, Catanduva BlackLizzards, DeepStep Mini Chickens (gm "A definir").
-- Pendente: campeão Donut 24/25 (Oilers x Capivaras) e campeão Bad Boys 25/26 (Carcarás x Outlawz).

create table if not exists public.season_team_history (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null references public.seasons(id),
  team_id uuid not null references public.teams(id),
  name_at_time text not null,
  conference text check (conference in ('Donut','Bad Boys')),
  wins int not null, ties int not null default 0, losses int not null,
  conference_position int,
  source text not null check (source in ('planilha','jogos')),
  created_at timestamptz not null default now(),
  unique (season_id, team_id));
create table if not exists public.season_champions (
  season_id uuid primary key references public.seasons(id),
  cancelled boolean not null default false,
  league_champion_id uuid references public.teams(id),
  donut_champion_id uuid references public.teams(id),
  donut_runner_up_id uuid references public.teams(id),
  bad_boys_champion_id uuid references public.teams(id),
  bad_boys_runner_up_id uuid references public.teams(id),
  note text, created_at timestamptz not null default now());
alter table public.season_team_history enable row level security;
alter table public.season_champions enable row level security;
create policy "leitura publica" on public.season_team_history for select to anon, authenticated using (true);
create policy "leitura publica" on public.season_champions for select to anon, authenticated using (true);
grant select on public.season_team_history, public.season_champions to anon, authenticated;
create index if not exists season_team_history_team_idx on public.season_team_history(team_id);

insert into public.seasons (label,start_year,end_year,total_weeks,is_current,is_completed)
select '08/09',2008,2009,17,false,true where not exists (select 1 from public.seasons where label='08/09');
insert into public.teams (name,abbreviation,slug,gm_id,is_active)
select v.name,v.ab,v.slug,'30d72ecf-cef3-40ea-8368-df79bbf2919b',false
from (values ('San Diego Spikes','SDS','san-diego-spikes'),('São Bernardo Furnitures','SBF','sao-bernardo-furnitures'),
 ('Natal Suncity','NSC','natal-suncity'),('Vila Real Junkheads','VRJ','vila-real-junkheads'),
 ('Bauru Whitout Tomato is Mixed','BWT','bauru-whitout-tomato-is-mixed'),('Catanduva BlackLizzards','CBL','catanduva-blacklizzards'),
 ('DeepStep Mini Chickens','DMC','deepstep-mini-chickens')) v(name,ab,slug)
where not exists (select 1 from public.teams t where t.name=v.name);

