x as (select s.id sid,g.home_team_id t,(g.home_score>g.away_score)::int w,(g.home_score=g.away_score)::int e,(g.home_score<g.away_score)::int l from public.games g join public.seasons s on s.id=g.season_id where g.status='final' and not g.is_playoff and s.label in ('19/20','20/21','21/22','22/23','23/24','24/25','25/26')
 union all select s.id,g.away_team_id,(g.away_score>g.home_score)::int,(g.home_score=g.away_score)::int,(g.away_score<g.home_score)::int from public.games g join public.seasons s on s.id=g.season_id where g.status='final' and not g.is_playoff and s.label in ('19/20','20/21','21/22','22/23','23/24','24/25','25/26')),
t as (select sid,x.t team_id,sum(w)::int w,sum(e)::int e,sum(l)::int l from x group by 1,2)
select s.id,tm.id,coalesce(ov.nm,k.name),case r.c when 'D' then 'Donut' else 'Bad Boys' end,t.w,t.e,t.l,r.pos,'jogos'
from r join k on k.i=r.i join tm on tm.name=k.name join public.seasons s on s.label=r.season join t on t.sid=s.id and t.team_id=tm.id left join ov on ov.season=r.season and ov.i=r.i;

-- 24/25–25/26 (jogos; conferência atual; posição por V, E, nome)
insert into public.season_team_history (season_id,team_id,name_at_time,conference,wins,ties,losses,conference_position,source)
with x as (select s.id sid,g.home_team_id t,(g.home_score>g.away_score)::int w,(g.home_score=g.away_score)::int e,(g.home_score<g.away_score)::int l from public.games g join public.seasons s on s.id=g.season_id where g.status='final' and not g.is_playoff and s.label in ('19/20','20/21','21/22','22/23','23/24','24/25','25/26')
 union all select s.id,g.away_team_id,(g.away_score>g.home_score)::int,(g.home_score=g.away_score)::int,(g.away_score<g.home_score)::int from public.games g join public.seasons s on s.id=g.season_id where g.status='final' and not g.is_playoff and s.label in ('19/20','20/21','21/22','22/23','23/24','24/25','25/26')),
t as (select sid,x.t team_id,sum(w)::int w,sum(e)::int e,sum(l)::int l from x group by 1,2),
t2 as (select t.*,tt.name,tt.conference from t join public.teams tt on tt.id=t.team_id join public.seasons s on s.id=t.sid where s.label in ('24/25','25/26'))
select sid,team_id,name,conference,w,e,l,row_number() over (partition by sid,conference order by w desc,e desc,name),'jogos' from t2;

-- campeões
insert into public.season_champions (season_id,cancelled,league_champion_id,donut_champion_id,donut_runner_up_id,bad_boys_champion_id,bad_boys_runner_up_id,note)
with tm as (select distinct on (name) id,name from public.teams order by name,(select count(*) from public.games g where g.home_team_id=teams.id or g.away_team_id=teams.id) desc),
c(season,cancelled,lg,dc,dv,bc,bv,note) as (values ('08/09',false,'Cambuquira Pure Water','Floripa Waves','SP Horse Ride','Cambuquira Pure Water','Brasilia Twisted Trees',null),('09/10',false,'Dengue State Outlawz','Floripa Waves','SP Horse Ride','Dengue State Outlawz','RJ Drugdealers',null),('10/11',false,'Pinheiros Racecars','Pinheiros Racecars','Campos Oilers','Dengue State Outlawz','Brasilia Twisted Trees',null),('11/12',false,'Campos Oilers','Campos Oilers','Campos Light City','São Bernardo Furnitures','DeepStep Ballers',null),('12/13',false,'Floripa Waves','Floripa Waves','Pará Papão','Recife Gold Lions','DeepStep Ballers',null),('13/14',false,'JPA KissFlowers','Campos Oilers','Floripa Waves','JPA KissFlowers','São Paulo TrafficJam',null),('14/15',false,'Floripa Waves','Floripa Waves','Santo André Balboas','Porto Alegre Ornitorrincos','RJ Drugdealers',null),('15/16',false,'Campinas Color Blinds','Campos Oilers','January River DJs','Campinas Color Blinds','Dengue State Outlawz',null),('16/17',false,'Campos Oilers','Campos Oilers','Floripa Waves','Campinas Color Blinds','DeepStep Ballers',null),('17/18',false,'Campos Oilers','Campos Oilers','January River DJs','Campinas Color Blinds','São Paulo TrafficJam',null),('18/19',false,'Palmas Mamiferos','Palmas Mamiferos','Campos Oilers','São Paulo TrafficJam','Campinas Color Blinds',null),('19/20',true,null,null,null,null,null,'Temporada cancelada (COVID)'),('20/21',false,'Palmas Mamiferos','Palmas Mamiferos','Campos Oilers','Blumenau Assassins','Recife Crabs',null),('21/22',false,'Cambuquira Pure Water','João Pessoa Fats','Pará Papão','Cambuquira Pure Water','Recife Gold Lions',null),('22/23',false,'Floripa Waves','Floripa Waves','Pará Papão','Tijuca Rocks','Cambuquira Pure Water',null),('23/24',false,'Blumenau Assassins','Palmas Mamiferos','Floripa Waves','Blumenau Assassins','JPA KissFlowers',null),('24/25',false,'Dengue State Outlawz',null,null,'Dengue State Outlawz','Blumenau Assassins','Final Donut: Campos Oilers x Rio Preto Capivaras (campeão a confirmar)'),('25/26',false,'Floripa Waves','Floripa Waves','Lavras Big Balls',null,null,'Final Bad Boys: Brasilia Carcarás x Dengue State Outlawz (campeão a confirmar)'))
select s.id,c.cancelled,(select id from tm where name=c.lg),(select id from tm where name=c.dc),(select id from tm where name=c.dv),(select id from tm where name=c.bc),(select id from tm where name=c.bv),c.note
from c join public.seasons s on s.label=c.season;
;
